from __future__ import annotations

import json
import logging
from dataclasses import dataclass, field
from typing import Any, Iterable, Mapping, Protocol

from fastapi import APIRouter, Depends, HTTPException, Request, status
from pydantic import BaseModel, ConfigDict, Field

logger = logging.getLogger(__name__)

SENSITIVE_AUTH_KEYS = frozenset(
    {
        "access_token",
        "authorization",
        "assertion",
        "bearer",
        "id_token",
        "refresh_token",
        "saml_assertion",
        "token",
    }
)

SAML_ROLE_KEYS = (
    "http://schemas.microsoft.com/ws/2008/06/identity/claims/role",
    "http://schemas.xmlsoap.org/claims/group",
)
SAML_SUBJECT_KEYS = (
    "nameid",
    "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier",
)
USERNAME_KEYS = ("preferred_username", "upn", "email", "username")
DISPLAY_NAME_KEYS = ("name", "display_name")


class ActorContext(BaseModel):
    model_config = ConfigDict(frozen=True)

    actor_id: str
    issuer: str
    subject: str
    username: str
    display_name: str
    auth_type: str
    permissions: tuple[str, ...] = Field(default_factory=tuple)
    group_refs: tuple[str, ...] = Field(default_factory=tuple)

    def audit_actor(self) -> dict[str, str]:
        return {
            "actor_id": self.actor_id,
            "issuer": self.issuer,
            "subject": self.subject,
            "username": self.username,
        }


class WriteCommand(BaseModel):
    document_id: str
    value: str


class WriteResult(BaseModel):
    document_id: str
    actor_id: str
    outcome: str = "written"


class BusinessMutationSink(Protocol):
    def write(self, *, actor: ActorContext, command: WriteCommand) -> WriteResult:
        ...


class AuditSink(Protocol):
    def record(
        self,
        *,
        actor: ActorContext,
        action: str,
        payload: Mapping[str, Any],
    ) -> None:
        ...


class InMemoryBusinessMutationSink:
    def __init__(self) -> None:
        self.calls: list[dict[str, Any]] = []

    def write(self, *, actor: ActorContext, command: WriteCommand) -> WriteResult:
        self.calls.append(
            {
                "actor": actor.audit_actor(),
                "command": command.model_dump(),
            }
        )
        return WriteResult(document_id=command.document_id, actor_id=actor.actor_id)


class InMemoryAuditSink:
    def __init__(self) -> None:
        self.calls: list[dict[str, Any]] = []

    def record(
        self,
        *,
        actor: ActorContext,
        action: str,
        payload: Mapping[str, Any],
    ) -> None:
        self.calls.append(
            {
                "actor": actor.audit_actor(),
                "action": action,
                "payload": dict(payload),
            }
        )


def _normalize_token(value: Any) -> str:
    return str(value).strip().lower()


def _iter_values(value: Any) -> Iterable[str]:
    if value is None:
        return ()
    if isinstance(value, str):
        return (value,)
    if isinstance(value, (list, tuple, set, frozenset)):
        return tuple(str(item) for item in value)
    return (str(value),)


def _iter_scope_values(value: Any) -> Iterable[str]:
    if value is None:
        return ()
    if isinstance(value, str):
        return tuple(part for part in value.split() if part.strip())
    return _iter_values(value)


def _first_non_empty(claims: Mapping[str, Any], *keys: str) -> str | None:
    for key in keys:
        value = claims.get(key)
        if value is None:
            continue
        text = str(value).strip()
        if text:
            return text
    return None


def redact_auth_payload(value: Any) -> Any:
    if isinstance(value, Mapping):
        redacted: dict[str, Any] = {}
        for key, item in value.items():
            if _normalize_token(key) in SENSITIVE_AUTH_KEYS:
                redacted[str(key)] = "[REDACTED]"
            else:
                redacted[str(key)] = redact_auth_payload(item)
        return redacted
    if isinstance(value, list):
        return [redact_auth_payload(item) for item in value]
    if isinstance(value, tuple):
        return tuple(redact_auth_payload(item) for item in value)
    if isinstance(value, str) and value.lower().startswith("bearer "):
        return "Bearer [REDACTED]"
    return value


@dataclass(slots=True)
class AuthPolicy:
    permission_map: Mapping[str, set[str]] = field(
        default_factory=lambda: {
            "reviewers": {"document.read"},
            "writers": {"document.read", "document.write"},
            "auditors": {"audit.read"},
        }
    )

    def normalize_actor(
        self,
        claims: Mapping[str, Any],
        *,
        auth_type: str,
    ) -> ActorContext:
        issuer = _first_non_empty(claims, "iss", "issuer", "saml_issuer") or "unknown-issuer"
        subject = _first_non_empty(claims, "sub", *SAML_SUBJECT_KEYS, "uid")
        username = _first_non_empty(claims, *USERNAME_KEYS) or subject
        display_name = _first_non_empty(claims, *DISPLAY_NAME_KEYS)

        if not username and not subject:
            raise HTTPException(
                status_code=status.HTTP_401_UNAUTHORIZED,
                detail="Anonymous caller is not allowed.",
            )

        resolved_subject = subject or username or "anonymous"
        resolved_username = username or resolved_subject
        resolved_display_name = display_name or resolved_username

        group_refs = self._group_refs(claims)
        permissions = self._permissions(claims, group_refs)

        logger.info(
            "normalized identity claims %s",
            redact_auth_payload(dict(claims)),
        )

        return ActorContext(
            actor_id=f"{issuer}:{resolved_subject}",
            issuer=issuer,
            subject=resolved_subject,
            username=resolved_username,
            display_name=resolved_display_name,
            auth_type=auth_type,
            permissions=tuple(sorted(permissions)),
            group_refs=tuple(sorted(group_refs)),
        )

    def require_permission(self, actor: ActorContext, permission: str) -> ActorContext:
        if permission not in actor.permissions:
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail=f"Missing required permission '{permission}'.",
            )
        return actor

    def _group_refs(self, claims: Mapping[str, Any]) -> set[str]:
        refs: set[str] = set()
        for key in ("groups", "roles", "role", *SAML_ROLE_KEYS):
            for value in _iter_values(claims.get(key)):
                token = _normalize_token(value)
                if token:
                    refs.add(token)
        return refs

    def _permissions(self, claims: Mapping[str, Any], group_refs: set[str]) -> set[str]:
        permissions: set[str] = set()

        for ref in group_refs:
            permissions.update(self.permission_map.get(ref, set()))

        for key in ("permissions", "permission"):
            for value in _iter_values(claims.get(key)):
                token = _normalize_token(value)
                if not token:
                    continue
                permissions.update(self.permission_map.get(token, set()))
                if _looks_like_permission(token):
                    permissions.add(token)

        for key in ("scope", "scp"):
            for value in _iter_scope_values(claims.get(key)):
                token = _normalize_token(value)
                if not token:
                    continue
                permissions.update(self.permission_map.get(token, set()))
                if _looks_like_permission(token):
                    permissions.add(token)

        return permissions


def _looks_like_permission(token: str) -> bool:
    return ":" in token or "." in token


def get_auth_policy(request: Request) -> AuthPolicy:
    return getattr(request.app.state, "auth_policy", AuthPolicy())


def get_business_mutation_sink(request: Request) -> BusinessMutationSink:
    sink = getattr(request.app.state, "business_mutation_sink", None)
    if sink is None:
        sink = InMemoryBusinessMutationSink()
        request.app.state.business_mutation_sink = sink
    return sink


def get_audit_sink(request: Request) -> AuditSink:
    sink = getattr(request.app.state, "audit_sink", None)
    if sink is None:
        sink = InMemoryAuditSink()
        request.app.state.audit_sink = sink
    return sink


def _resolve_auth_type(request: Request, claims: Mapping[str, Any]) -> str:
    explicit = request.headers.get("x-auth-provider")
    if explicit:
        return explicit.strip().lower()
    if any(key in claims for key in SAML_SUBJECT_KEYS + SAML_ROLE_KEYS):
        return "saml"
    return "oidc"


def _claims_from_request(request: Request) -> Mapping[str, Any]:
    raw_claims = request.headers.get("x-auth-claims")
    if not raw_claims:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Anonymous caller is not allowed.",
        )

    try:
        parsed = json.loads(raw_claims)
    except json.JSONDecodeError as exc:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Authentication context could not be parsed.",
        ) from exc

    if not isinstance(parsed, dict):
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Authentication context must be an object.",
        )

    return parsed


def get_actor_context(
    request: Request,
    policy: AuthPolicy = Depends(get_auth_policy),
) -> ActorContext:
    claims = _claims_from_request(request)
    return policy.normalize_actor(claims, auth_type=_resolve_auth_type(request, claims))


def require_permission(permission: str):
    def dependency(
        actor: ActorContext = Depends(get_actor_context),
        policy: AuthPolicy = Depends(get_auth_policy),
    ) -> ActorContext:
        return policy.require_permission(actor, permission)

    return dependency


router = APIRouter(prefix="/auth", tags=["auth"])


@router.get("/me", response_model=ActorContext)
def get_me(actor: ActorContext = Depends(get_actor_context)) -> ActorContext:
    return actor


@router.post(
    "/protected-write",
    response_model=WriteResult,
    status_code=status.HTTP_202_ACCEPTED,
)
def protected_write(
    command: WriteCommand,
    actor: ActorContext = Depends(require_permission("document.write")),
    business_sink: BusinessMutationSink = Depends(get_business_mutation_sink),
    audit_sink: AuditSink = Depends(get_audit_sink),
) -> WriteResult:
    result = business_sink.write(actor=actor, command=command)
    audit_sink.record(
        actor=actor,
        action="document.write",
        payload={"document_id": command.document_id},
    )
    return result

