        "x-auth-provider": provider,
        "x-auth-claims": json.dumps(claims),
    }


def test_oidc_claims_map_permissions_deterministically_and_redact_tokens(
    auth_policy: AuthPolicy,
    caplog: pytest.LogCaptureFixture,
) -> None:
    caplog.set_level(logging.INFO, logger="backend.auth.main_module")

    actor = auth_policy.normalize_actor(
        {
            "iss": "https://issuer.example.test",
            "sub": "user-123",
            "preferred_username": "alex",
            "name": "Alex Writer",
            "groups": ["writers", "reviewers"],
            "scope": "openid profile document.write",
            "access_token": "secret-access-token",
            "id_token": "secret-id-token",
        },
        auth_type="oidc",
    )

    assert actor.actor_id == "https://issuer.example.test:user-123"
    assert actor.username == "alex"
    assert actor.display_name == "Alex Writer"
    assert actor.permissions == ("document.read", "document.write")
    assert actor.group_refs == ("reviewers", "writers")
    assert "secret-access-token" not in caplog.text
    assert "secret-id-token" not in caplog.text
    assert "[REDACTED]" in caplog.text


